(function(){var b=document.querySelector('.nav-menu-toggle'),m=document.getElementById('zvm-nav-links');if(!b||!m)return;function setOpen(open){b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');m.classList.toggle('is-open',open);}b.addEventListener('click',function(){setOpen(b.getAttribute('aria-expanded')!=='true');});m.addEventListener('click',function(e){if(e.target.closest('a'))setOpen(false);});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&b.getAttribute('aria-expanded')==='true'){setOpen(false);b.focus();}});})();
